  "analysis": {
    "statement": "Cho tam giác $ABC$ vuông tại $A$ có $AB = 6$ cm, $AC = 8$ cm. Tính độ dài cạnh huyền $BC$ và độ dài đường cao $AH$ hạ từ $A$ xuống $BC$.",
    "language": "vi",
    "topic": "geometry",
    "subtopic": "quan_he_luong_trong_tam_giac_vuong",
    "gradeLevel": 9,
    "withinCurriculum": true,
    "concepts": ["tam_giac_vuong", "dinh_pytago", "he_thuc_luong_trong_tam_giac_vuong", "b^2 = a.c' va h^2 = b'.c'"],
    "givens": [
      "Tam giác ABC vuông tại A",
      "AB = 6 cm",
      "AC = 8 cm"
    ],
    "unknowns": [
      "BC (cạnh huyền)",
      "AH (đường cao)"
    ],
    "constraints": [],
    "status": "solvable",
    "statusReason": null,
    "interpretationNotes": []
  },
  "strategy": "Mình sẽ dùng định lý Py-ta-go để tìm cạnh huyền $BC$ trước, vì đây là cạnh huyền của tam giác vuông. Sau đó, mình sẽ dùng hệ thức lượng trong tam giác vuông (cạnh góc vuông bình bằng cạnh huyền nhân với hình chiếu của nó) để tìm hình chiếu $BH$ và $CH$, rồi dùng hệ thức $AH^2 = BH \\cdot CH$ hoặc $AH = \\frac{AB \\cdot AC}{BC}$ để tính đường cao $AH$.",
  "hints": [
    {
      "id": "h1",
      "level": 1,
      "question": "Trong tam giác vuông $ABC$ vuông tại $A$, ta đã biết hai cạnh góc vuông $AB$ và $AC$. Để tìm cạnh huyền $BC$, công thức nào là quen thuộc nhất?",
      "cue": "Định lý Py-ta-go",
      "explanation": "Định lý Py-ta-go nói rằng bình phương cạnh huyền bằng tổng bình phương hai cạnh góc vuông.",
      "math": "BC^2 = AB^2 + AC^2",
      "stepId": "g1",
      "focus": ["seg_AB", "seg_AC", "seg_BC"]
    },
    {
      "id": "h2",
      "level": 2,
      "question": "Sau khi tính được $BC$, mình cần tìm đường cao $AH$. Có một hệ thức liên quan trực tiếp đến đường cao và hai cạnh góc vuông không?",
      "cue": "Hệ thức lượng: Tích hai cạnh góc vuông bằng cạnh huyền nhân đường cao tương ứng",
      "explanation": "Ta có $AB \\cdot AC = BC \\cdot AH$. Vì đã biết $AB, AC$ và vừa tìm được $BC$, nên có thể tính ngay $AH$.",
      "math": "AH = \\frac{AB \\cdot AC}{BC}",
      "stepId": "g2",
      "focus": ["seg_AB", "seg_AC", "seg_BC", "seg_AH"]
    }
  ],
  "steps": [
    {
      "id": "g1",
      "title": "Tính cạnh huyền BC",
      "explanation": "Vì tam giác $ABC$ vuông tại $A$, ta áp dụng định lý Py-ta-go cho tam giác $ABC$. Bình phương cạnh huyền $BC$ bằng tổng bình phương hai cạnh góc vuông $AB$ và $AC$.",
      "math": "BC^2 = AB^2 + AC^2 = 6^2 + 8^2 = 36 + 64 = 100",
      "reason": "Định lý Py-ta-go",
      "geometryActions": [
        {"action": "show", "targets": ["seg_AB", "seg_AC", "seg_BC"]}
      ]
    },
    {
      "id": "g2",
      "title": "Tính độ dài cạnh BC",
      "explanation": "Từ $BC^2 = 100$, ta suy ra độ dài cạnh $BC$ là căn bậc hai của 100. Vì độ dài là số dương nên $BC = 10$ cm.",
      "math": "BC = \\sqrt{100} = 10 \\text{ (cm)}",
      "reason": "Tính toán đơn giản",
      "geometryActions": [
        {"action": "show", "targets": ["seg_BC"]}
      ]
    },
    {
      "id": "g3",
      "title": "Tính đường cao AH",
      "explanation": "Mình dùng hệ thức lượng trong tam giác vuông: Tích hai cạnh góc vuông bằng cạnh huyền nhân với đường cao tương ứng ($AB \\cdot AC = BC \\cdot AH$). Thay các giá trị đã biết vào để tìm $AH$.",
      "math": "6 \\cdot 8 = 10 \\cdot AH \\Rightarrow 48 = 10 \\cdot AH \\Rightarrow AH = \\frac{48}{10} = 4.8 \\text{ (cm)}",
      "reason": "Hệ thức lượng trong tam giác vuông",
      "geometryActions": [
        {"action": "show", "targets": ["seg_AH"]}
      ]
    }
  ],
  "finalAnswer": {
    "text": "Độ dài cạnh $BC$ là $10$ cm và độ dài đường cao $AH$ là $4.8$ cm.",
    "math": "BC = 10 \\text{ cm}, AH = 4.8 \\text{ cm}"
  },
